  if(kind==="chat"&&result.assistantMessageId){delete receipt.reply;receipt.replyFromMessage=true}
  await dbRun(env.DB,"UPDATE imai_request_receipts SET state='complete',result_json=? WHERE user_id=? AND request_id=? AND state='pending'",JSON.stringify(receipt),user.id,id);
