function videoProjectSseEvent(block){
 const event=block.match(/^event:\s*(\S+)/m)?.[1],data=block.split("\n").filter(x=>x.startsWith("data:")).map(x=>x.slice(5).trimStart()).join("\n");
 if(event==="error")return {error:/quota|zerogpu|gpu.*available|rate.limit/i.test(data)?"免费 GPU 额度或容量不足":"免费模型未能生成视频"};
 if(event==="complete"){let v;try{v=JSON.parse(data)}catch{return {error:"视频结果格式无效"}}const url=fvOutput(v,FV_LTX);return url?{url}:{error:"免费模型未返回有效 MP4"}}
 return null;
}
async function videoProjectSse(resp){
 if(!resp.ok||!resp.body)throw Error("免费模型状态连接失败");
 const reader=resp.body.getReader(),decoder=new TextDecoder();let buffer="";
 try{
  while(true){
   const {done,value}=await reader.read();if(done){const result=videoProjectSseEvent(buffer.replace(/\r/g,""));return result||{error:"免费模型未返回视频结果"}}
   buffer+=decoder.decode(value,{stream:true});buffer=buffer.replace(/\r\n/g,"\n");
   let end;while((end=buffer.indexOf("\n\n"))>=0){const block=buffer.slice(0,end);buffer=buffer.slice(end+2);const result=videoProjectSseEvent(block);if(result)return result}
   if(buffer.length>131072)throw Error("视频状态响应过大");
  }
 }finally{await reader.cancel().catch(()=>{})}
}
async function videoProjectVerify(url){
 const r=await fetch(url,{headers:{accept:"video/mp4",range:"bytes=0-63"},redirect:"manual",signal:AbortSignal.timeout(15000)});
 if(!r.ok||!r.body)return false;
 const type=(r.headers.get("content-type")||"").toLowerCase();
 const reader=r.body.getReader();try{
  const header=new Uint8Array(12);let size=0;
  while(size<header.length){const {done,value}=await reader.read();if(done)break;const part=value.subarray(0,header.length-size);header.set(part,size);size+=part.length}
  return /^(?:video\/mp4|application\/octet-stream)/.test(type)&&size>=12&&String.fromCharCode(...header.slice(4,8))==="ftyp";
 }finally{await reader.cancel().catch(()=>{})}
}
