async function fvMedia(req,env,user,id){
 if(!fvId(id))return fail("视频编号无效",400);
 const key=user.id+"/"+id,info=await env.MEDIA?.head(key);
 if(!info||info.httpMetadata?.contentType!=="video/mp4")return fail("视频不存在或没有权限",404);
 const size=info.size,range=req.headers.get("range");let lo=0,hi=size-1,status=200;
 if(range){
  const m=/^bytes=(\d*)-(\d*)$/.exec(range.trim());
  if(!m||!m[1]&&!m[2])return new Response(null,{status:416,headers:{"content-range":"bytes */"+size}});
  lo=m[1]?Number(m[1]):Math.max(0,size-Number(m[2]));hi=m[1]?(m[2]?Number(m[2]):size-1):size-1;
  if(!Number.isSafeInteger(lo)||!Number.isSafeInteger(hi)||lo>hi||lo>=size)return new Response(null,{status:416,headers:{"content-range":"bytes */"+size}});
  hi=Math.min(hi,size-1);status=206;
 }
 const obj=await env.MEDIA.get(key,{range:status===206?{offset:lo,length:hi-lo+1}:undefined});
 if(!obj)return fail("视频不可用",404);
 const headers={"content-type":"video/mp4","cache-control":"private,max-age=120","content-disposition":"inline","accept-ranges":"bytes","content-length":String(hi-lo+1),"x-content-type-options":"nosniff"};
 if(status===206)headers["content-range"]="bytes "+lo+"-"+hi+"/"+size;
 return new Response(obj.body,{status,headers});
}

