 if(req.method==="GET"&&(path==="/imai-robot-idle.gif"||path==="/imai-robot-motion.gif"))return new Response(fromB64(path==="/imai-robot-idle.gif"?IMAI_ROBOT_IDLE:IMAI_ROBOT_MOTION),{headers:secureHeaders({"content-type":"image/gif","cache-control":"public, max-age=86400"})});
