  const png=path==="/apple-touch-icon.png"?ICON_180_BASE64:path==="/app-icon-192.png"?ICON_192_BASE64:path==="/app-icon-maskable.png"?ICON_MASKABLE_BASE64:ICON_512_BASE64;
  return new Response(fromB64(png),{headers:secureHeaders({"content-type":"image/png","cache-control":"no-store"})});
