 if(req.method==="GET"&&path==="/health")return response({ok:true,app:"IMAI 独立工作台",version:VERSION,ownHosting:true,database:Boolean(env.DB),externalFreeOnly:true,storage:Boolean(env.MEDIA),limits:{freeTextDailyCap:null,freeTextSiteDailyCap:null}});
